
import React from "react";
import Progress from "../components/Progress";
import CentreRegister from "../components/CentreRegister";
import Preloader from "../helper/Preloader";
import HeaderOne from "../components/HeaderOne";
import FooterOne from "../components/FooterOne";
import BreadcrumbNine from "../components/BreadcrumbNine";
import { SEO } from "../utils/SEO";

const CentreRegisterPage = () => {
  const can = window.location.href;

	return (
		<>
		 <SEO
        title="4ceps | Centre Registration – List Your Healthcare Facility"
        description="Register your healthcare centre on 4ceps to reach more patients. List your hospital, clinic or diagnostic centre easily and connect with users for booking services."
        url={can}
      />
			{/* Preloader */}
			<Preloader />

			{/* HeaderOne */}
			<HeaderOne />

			{/* Breadcrumb */}
			<BreadcrumbNine />

			{/* Progress */}
			<Progress />

			{/* Login */}
			<CentreRegister />

			{/* FooterOne */}
			<FooterOne />
		</>
	);
};

export default CentreRegisterPage;